type SpiceDialect = "generic" | "spice3" | "ngspice" | "ltspice" | "pspice" | "xyce";
interface SourceSpan {
    start: number;
    end: number;
}
interface SpiceParseOptions {
    dialect?: SpiceDialect;
    preserveTrivia?: boolean;
    preserveRaw?: boolean;
    strict?: boolean;
}
interface SpiceSerializeOptions {
    dialect?: SpiceDialect;
    format?: "pretty" | "preserve";
    lineWidth?: number;
    continuation?: "plus" | "backslash";
    end?: "auto" | "always" | "never";
    numericFormat?: "preserve" | "normalized";
}
interface SpiceNodeInit {
    originalSource?: string;
    sourceSpan?: SourceSpan;
    trailingComment?: string;
}
type SpiceCardKind = "element" | "directive" | "comment" | "blank" | "raw";

declare abstract class SpiceTrivia extends SpiceNode {
    abstract readonly type: "comment" | "blank";
}

declare abstract class SpiceNode {
    abstract readonly type: string;
    sourceSpan?: SourceSpan;
    leadingTrivia: SpiceTrivia[];
    trailingComment?: string;
    constructor(init?: SpiceNodeInit);
    abstract getChildren(): SpiceNode[];
    abstract toSource(options?: SpiceSerializeOptions): string;
    getString(options?: SpiceSerializeOptions): string;
}

type SourcePosition = {
    offset: number;
    line: number;
    column: number;
};
type SourceRange = {
    start: SourcePosition;
    end: SourcePosition;
};
type SpiceTokenType = "directive" | "identifier" | "number" | "string" | "operator" | "punctuation" | "comment" | "continuation" | "newline" | "whitespace" | "error";
type BaseToken = {
    type: SpiceTokenType;
    raw: string;
    range: SourceRange;
};
type SpiceTokenDirective = BaseToken & {
    type: "directive";
    value: string;
};
type SpiceTokenIdentifier = BaseToken & {
    type: "identifier";
    value: string;
};
type SpiceTokenNumber = BaseToken & {
    type: "number";
    value: number | null;
    unitSuffix?: string;
};
type SpiceTokenString = BaseToken & {
    type: "string";
    value: string;
    quote: '"' | "'";
};
type SpiceTokenOperator = BaseToken & {
    type: "operator";
    value: string;
};
type SpiceTokenPunctuation = BaseToken & {
    type: "punctuation";
    value: string;
};
type SpiceTokenComment = BaseToken & {
    type: "comment";
    value: string;
    marker: "*" | ";" | "$";
};
type SpiceTokenContinuation = BaseToken & {
    type: "continuation";
};
type SpiceTokenNewline = BaseToken & {
    type: "newline";
    raw: "\n" | "\r\n" | "\r";
};
type SpiceTokenWhitespace = BaseToken & {
    type: "whitespace";
};
type SpiceTokenError = BaseToken & {
    type: "error";
    message: string;
};
type SpiceToken = SpiceTokenDirective | SpiceTokenIdentifier | SpiceTokenNumber | SpiceTokenString | SpiceTokenOperator | SpiceTokenPunctuation | SpiceTokenComment | SpiceTokenContinuation | SpiceTokenNewline | SpiceTokenWhitespace | SpiceTokenError;
type SpiceTokenizerError = {
    message: string;
    raw: string;
    range: SourceRange;
};
type SpiceTokenizationResult = {
    tokens: SpiceToken[];
    errors: SpiceTokenizerError[];
    source: {
        text: string;
        lineCount: number;
    };
};
type SpiceTokenizerOptions = {
    preserveWhitespace?: boolean;
    preserveComments?: boolean;
    normalizeNumbers?: boolean;
};
type SpiceLogicalCard = {
    tokens: SpiceToken[];
    originalSource: string;
    range: SourceRange;
    leadingNewlineRaw?: "\n" | "\r\n" | "\r";
    childCards?: SpiceLogicalCard[];
    endCard?: SpiceLogicalCard;
};

type SpiceCardConstructor = {
    spiceTokenKeys: string[];
    fromSpiceTokens(card: SpiceLogicalCard): SpiceCard;
};
declare abstract class SpiceCard extends SpiceNode {
    abstract readonly cardKind: SpiceCardKind;
    originalSource?: string;
    constructor(init?: SpiceNodeInit);
    static classes: Record<string, SpiceCardConstructor>;
    static register(newClass: SpiceCardConstructor): void;
    static parseSpiceTokens(card: SpiceLogicalCard): SpiceCard;
}

declare abstract class DotCommand extends SpiceCard {
    readonly cardKind: "directive";
    abstract command: string;
}

declare abstract class AnalysisCommand extends DotCommand {
}

declare function tokensToLogicalCards(tokens: SpiceToken[]): SpiceLogicalCard[];
declare function significantTokens(tokens: SpiceToken[]): SpiceToken[];
declare function tokenValue(token: SpiceToken | undefined): string | undefined;

declare function parseToSpiceTokens(source: string, options?: SpiceTokenizerOptions): SpiceTokenizationResult;

declare function tokenizeSpice(source: string, options?: SpiceTokenizerOptions): SpiceTokenizationResult;

declare class NodeRef {
    name: string;
    constructor(name: string);
    static ground(): NodeRef;
    getString(): string;
}

declare class SpiceValue {
    raw: string;
    constructor(value: string | number);
    getString(): string;
}

declare abstract class SourceWaveform extends SpiceNode {
    getChildren(): SpiceNode[];
}

declare class SpiceExpression {
    raw: string;
    constructor(raw: string);
    getString(): string;
}

type NodeRefInput = string | NodeRef;
type SpiceValueInput = string | number | SpiceValue | SpiceExpression;
type ParamsInput = Record<string, SpiceValueInput> | Array<[string, SpiceValueInput]> | ParamList;
type SourceWaveformInput = SourceWaveform;
interface AcSpec {
    magnitude?: SpiceValue;
    phase?: SpiceValue;
}
type AcSpecInput = SpiceValueInput | {
    magnitude?: SpiceValueInput;
    phase?: SpiceValueInput;
};

declare class ParamList {
    private values;
    constructor(input?: ParamsInput);
    get(name: string): SpiceValue | undefined;
    set(name: string, value: SpiceValueInput): void;
    delete(name: string): boolean;
    entries(): Array<[string, SpiceValue]>;
    getString(_options?: SpiceSerializeOptions): string;
    get isEmpty(): boolean;
}

