    readonly originalSource: string;
    private constructor();
    static from(card: SpiceLogicalCard): SpiceTokenCard;
    head(): string;
    headRaw(): string;
    headDesignator(): string;
    arg(index: number): string | undefined;
    args(): string[];
    argsAfter(index: number): string[];
    argsUntilLast(): string[];
